  box-shadow: none
}

@media (forced-colors:active) {
  .docs-modern-theme ::-webkit-scrollbar-thumb,
  .docs-modern-theme ::-webkit-scrollbar-thumb:active,
  .docs-modern-theme ::-webkit-scrollbar-thumb:hover,
  .drive-modern-theme ::-webkit-scrollbar-thumb,
  .drive-modern-theme ::-webkit-scrollbar-thumb:active,
  .drive-modern-theme ::-webkit-scrollbar-thumb:hover,
  .workspace-modern-theme ::-webkit-scrollbar-thumb,
  .workspace-modern-theme ::-webkit-scrollbar-thumb:active,
  .workspace-modern-theme ::-webkit-scrollbar-thumb:hover,
  .google-modern-theme ::-webkit-scrollbar-thumb,
  .google-modern-theme ::-webkit-scrollbar-thumb:active,
  .google-modern-theme ::-webkit-scrollbar-thumb:hover,
  .material-docs-theme ::-webkit-scrollbar-thumb,
  .material-docs-theme ::-webkit-scrollbar-thumb:active,
  .material-docs-theme ::-webkit-scrollbar-thumb:hover {
    background-color: CanvasText
  }
}

@supports not selector(::-webkit-scrollbar) {
  .docs-modern-theme,
  .drive-modern-theme,
  .workspace-modern-theme,
  .google-modern-theme,
  .material-docs-theme {
    scrollbar-width: thin;
    scrollbar-color: var(--dt-outline-variant, rgb(218, 220, 224)) transparent
  }
}

